package org.beehive.jitnn.kernels;

import uk.ac.manchester.tornado.api.KernelContext;
import uk.ac.manchester.tornado.api.math.TornadoMath;
import uk.ac.manchester.tornado.api.types.HalfFloat;
import uk.ac.manchester.tornado.api.types.arrays.FloatArray;
import uk.ac.manchester.tornado.api.types.arrays.HalfFloatArray;
import uk.ac.manchester.tornado.api.types.arrays.IntArray;

/**
 * {@link FlashTiled64#forward} on FP16 q, k, v and o (FP32 products, softmax and accumulators),
 * generated by scripts/codegen/flash_tiled_half.py: half the memory traffic of the FP32 kernel for
 * inference in half precision. Same launch, meta layout, mask and lse. The backward kernels read
 * FP16 q, k, v and o and take and write FP32 gradients (training with FP16 activations), with the
 * launches of {@link FlashTiled64#backwardKV} and {@link FlashTiled64#backwardQ}.
 */
public final class FlashTiled64Half {

    private static final float MASKED = -3.0e38f;

    private FlashTiled64Half() {
    }

    public static void forward(KernelContext kc, HalfFloatArray q, HalfFloatArray k, HalfFloatArray v, FloatArray mask, HalfFloatArray o, FloatArray lse, int t, int s, int d,
            float scale, int causal, int hasMask, IntArray meta) {
        float[] qs = kc.allocateFloatLocalArray(4160);
        float[] ks = kc.allocateFloatLocalArray(2080);
        float[] vs = kc.allocateFloatLocalArray(2080);
        float[] ss = kc.allocateFloatLocalArray(2112);
        float[] part = kc.allocateFloatLocalArray(256);
        float[] mrow = kc.allocateFloatLocalArray(64);
        float[] lrow = kc.allocateFloatLocalArray(64);
        float[] arow = kc.allocateFloatLocalArray(64);
        int tx = kc.localIdx;
        int ty = kc.localIdy;
        int tid = ty * 16 + tx;
        int qBlocks = (t + 63) / 64;
        int z = kc.groupIdx / qBlocks;
        int q0 = (kc.groupIdx - z * qBlocks) * 64;
        int heads = meta.get(0);
        int b = z / heads;
        int hh = z - b * heads;
        int qBase = meta.get(5) + b * meta.get(6) + hh * meta.get(7);
        int qStr = meta.get(8);
        int kBase = meta.get(9) + b * meta.get(10) + hh * meta.get(11);
        int kStr = meta.get(12);
        int vBase = meta.get(13) + b * meta.get(14) + hh * meta.get(15);
        int vStr = meta.get(16);
        int oBase = meta.get(17) + b * meta.get(18) + hh * meta.get(19);
        int oStr = meta.get(20);
        int mBase = b * meta.get(1) + hh * meta.get(2);
        int mi = meta.get(3);
        int mj = meta.get(4);
        for (int e = tid; e < 4096; e += 256) {
            int r = e / 64;
            int c = e - r * 64;
            float x = 0.0f;
            if ((q0 + r < t) & (c < d)) {
                x = q.get(qBase + (q0 + r) * qStr + c).getFloat32();
            }
            qs[r * 65 + c] = x;
        }
        if (tid < 64) {
            mrow[tid] = MASKED;
            lrow[tid] = 0.0f;
        }
        float acc00 = 0.0f;
        float acc01 = 0.0f;
        float acc02 = 0.0f;
        float acc03 = 0.0f;
        float acc10 = 0.0f;
        float acc11 = 0.0f;
        float acc12 = 0.0f;
        float acc13 = 0.0f;
        float acc20 = 0.0f;
        float acc21 = 0.0f;
        float acc22 = 0.0f;
        float acc23 = 0.0f;
        float acc30 = 0.0f;
        float acc31 = 0.0f;
        float acc32 = 0.0f;
        float acc33 = 0.0f;
        int kEnd = s;
        if (causal != 0) {
            int last = q0 + 64;
            kEnd = last < s ? last : s;
        }
        int row = tid / 4;
        int quarter = tid - row * 4;
        for (int j0 = 0; j0 < kEnd; j0 += 32) {
            for (int e = tid; e < 2048; e += 256) {
                int r = e / 64;
                int c = e - r * 64;
                int j = j0 + r;
                float kv = 0.0f;
                float vv = 0.0f;
                if ((j < s) & (c < d)) {
                    kv = k.get(kBase + j * kStr + c).getFloat32();
                    vv = v.get(vBase + j * vStr + c).getFloat32();
                }
                ks[r * 65 + c] = kv;
                vs[r * 65 + c] = vv;
            }
            kc.localBarrier();
            float s00 = 0.0f;
            float s01 = 0.0f;
            float s10 = 0.0f;
            float s11 = 0.0f;
            float s20 = 0.0f;
            float s21 = 0.0f;
            float s30 = 0.0f;
            float s31 = 0.0f;
            for (int c = 0; c < 64; c++) {
                float a0 = qs[(ty + 0) * 65 + c];
                float a1 = qs[(ty + 16) * 65 + c];
                float a2 = qs[(ty + 32) * 65 + c];
                float a3 = qs[(ty + 48) * 65 + c];
                float k0 = ks[(tx + 0) * 65 + c];
                float k1 = ks[(tx + 16) * 65 + c];
                s00 += a0 * k0;
                s01 += a0 * k1;
                s10 += a1 * k0;
                s11 += a1 * k1;
                s20 += a2 * k0;
                s21 += a2 * k1;
                s30 += a3 * k0;
                s31 += a3 * k1;
            }
            {
                int qi = q0 + ty + 0;
                int j = j0 + tx + 0;
                float sv = MASKED;
                if ((qi < t) & (j < s) & ((causal == 0) | (j <= qi))) {
                    sv = s00 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + j * mj);
                    }
                }
                ss[(ty + 0) * 33 + tx + 0] = sv;
            }
            {
                int qi = q0 + ty + 0;
                int j = j0 + tx + 16;
                float sv = MASKED;
                if ((qi < t) & (j < s) & ((causal == 0) | (j <= qi))) {
                    sv = s01 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + j * mj);
                    }
                }
                ss[(ty + 0) * 33 + tx + 16] = sv;
            }
            {
                int qi = q0 + ty + 16;
                int j = j0 + tx + 0;
                float sv = MASKED;
                if ((qi < t) & (j < s) & ((causal == 0) | (j <= qi))) {
                    sv = s10 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + j * mj);
                    }
                }
                ss[(ty + 16) * 33 + tx + 0] = sv;
            }
            {
                int qi = q0 + ty + 16;
                int j = j0 + tx + 16;
                float sv = MASKED;
                if ((qi < t) & (j < s) & ((causal == 0) | (j <= qi))) {
                    sv = s11 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + j * mj);
                    }
                }
                ss[(ty + 16) * 33 + tx + 16] = sv;
            }
            {
                int qi = q0 + ty + 32;
                int j = j0 + tx + 0;
                float sv = MASKED;
                if ((qi < t) & (j < s) & ((causal == 0) | (j <= qi))) {
                    sv = s20 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + j * mj);
                    }
                }
                ss[(ty + 32) * 33 + tx + 0] = sv;
            }
            {
                int qi = q0 + ty + 32;
                int j = j0 + tx + 16;
                float sv = MASKED;
                if ((qi < t) & (j < s) & ((causal == 0) | (j <= qi))) {
                    sv = s21 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + j * mj);
                    }
                }
                ss[(ty + 32) * 33 + tx + 16] = sv;
            }
            {
                int qi = q0 + ty + 48;
                int j = j0 + tx + 0;
                float sv = MASKED;
                if ((qi < t) & (j < s) & ((causal == 0) | (j <= qi))) {
                    sv = s30 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + j * mj);
                    }
                }
                ss[(ty + 48) * 33 + tx + 0] = sv;
            }
            {
                int qi = q0 + ty + 48;
                int j = j0 + tx + 16;
                float sv = MASKED;
                if ((qi < t) & (j < s) & ((causal == 0) | (j <= qi))) {
                    sv = s31 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + j * mj);
                    }
                }
                ss[(ty + 48) * 33 + tx + 16] = sv;
            }
            kc.localBarrier();
            float lm = MASKED;
            for (int c = 0; c < 8; c++) {
                float sv = ss[row * 33 + quarter * 8 + c];
                lm = sv > lm ? sv : lm;
            }
            part[tid] = lm;
            kc.localBarrier();
            float mOld = mrow[row];
            float mNew = mOld;
            for (int c = 0; c < 4; c++) {
                float pm = part[row * 4 + c];
                mNew = pm > mNew ? pm : mNew;
            }
            float ls = 0.0f;
            for (int c = 0; c < 8; c++) {
                int at = row * 33 + quarter * 8 + c;
                float sv = ss[at];
                float p = sv > MASKED ? TornadoMath.exp(sv - mNew) : 0.0f;
                ss[at] = p;
                ls += p;
            }
            kc.localBarrier();
            part[tid] = ls;
            kc.localBarrier();
            if (quarter == 0) {
                float alpha = mOld > MASKED ? TornadoMath.exp(mOld - mNew) : 0.0f;
                lrow[row] = lrow[row] * alpha + part[row * 4] + part[row * 4 + 1] + part[row * 4 + 2] + part[row * 4 + 3];
                mrow[row] = mNew;
                arow[row] = alpha;
            }
            kc.localBarrier();
            float al0 = arow[ty + 0];
            acc00 = acc00 * al0;
            acc01 = acc01 * al0;
            acc02 = acc02 * al0;
            acc03 = acc03 * al0;
            float al1 = arow[ty + 16];
            acc10 = acc10 * al1;
            acc11 = acc11 * al1;
            acc12 = acc12 * al1;
            acc13 = acc13 * al1;
            float al2 = arow[ty + 32];
            acc20 = acc20 * al2;
            acc21 = acc21 * al2;
            acc22 = acc22 * al2;
            acc23 = acc23 * al2;
            float al3 = arow[ty + 48];
            acc30 = acc30 * al3;
            acc31 = acc31 * al3;
            acc32 = acc32 * al3;
            acc33 = acc33 * al3;
            for (int kk = 0; kk < 32; kk++) {
                float p0 = ss[(ty + 0) * 33 + kk];
                float p1 = ss[(ty + 16) * 33 + kk];
                float p2 = ss[(ty + 32) * 33 + kk];
                float p3 = ss[(ty + 48) * 33 + kk];
                float v0 = vs[kk * 65 + tx + 0];
                float v1 = vs[kk * 65 + tx + 16];
                float v2 = vs[kk * 65 + tx + 32];
                float v3 = vs[kk * 65 + tx + 48];
                acc00 += p0 * v0;
                acc01 += p0 * v1;
                acc02 += p0 * v2;
                acc03 += p0 * v3;
                acc10 += p1 * v0;
                acc11 += p1 * v1;
                acc12 += p1 * v2;
                acc13 += p1 * v3;
                acc20 += p2 * v0;
                acc21 += p2 * v1;
                acc22 += p2 * v2;
                acc23 += p2 * v3;
                acc30 += p3 * v0;
                acc31 += p3 * v1;
                acc32 += p3 * v2;
                acc33 += p3 * v3;
            }
            kc.localBarrier();
        }
        {
            int r = ty + 0;
            int qi = q0 + r;
            float l = lrow[r];
            float inv = l > 0.0f ? 1.0f / l : 0.0f;
            if ((qi < t) & (tx + 0 < d)) {
                o.set(oBase + qi * oStr + tx + 0, new HalfFloat(acc00 * inv));
            }
            if ((qi < t) & (tx + 16 < d)) {
                o.set(oBase + qi * oStr + tx + 16, new HalfFloat(acc01 * inv));
            }
            if ((qi < t) & (tx + 32 < d)) {
                o.set(oBase + qi * oStr + tx + 32, new HalfFloat(acc02 * inv));
            }
            if ((qi < t) & (tx + 48 < d)) {
                o.set(oBase + qi * oStr + tx + 48, new HalfFloat(acc03 * inv));
            }
        }
        {
            int r = ty + 16;
            int qi = q0 + r;
            float l = lrow[r];
            float inv = l > 0.0f ? 1.0f / l : 0.0f;
            if ((qi < t) & (tx + 0 < d)) {
                o.set(oBase + qi * oStr + tx + 0, new HalfFloat(acc10 * inv));
            }
            if ((qi < t) & (tx + 16 < d)) {
                o.set(oBase + qi * oStr + tx + 16, new HalfFloat(acc11 * inv));
            }
            if ((qi < t) & (tx + 32 < d)) {
                o.set(oBase + qi * oStr + tx + 32, new HalfFloat(acc12 * inv));
            }
            if ((qi < t) & (tx + 48 < d)) {
                o.set(oBase + qi * oStr + tx + 48, new HalfFloat(acc13 * inv));
            }
        }
        {
            int r = ty + 32;
            int qi = q0 + r;
            float l = lrow[r];
            float inv = l > 0.0f ? 1.0f / l : 0.0f;
            if ((qi < t) & (tx + 0 < d)) {
                o.set(oBase + qi * oStr + tx + 0, new HalfFloat(acc20 * inv));
            }
            if ((qi < t) & (tx + 16 < d)) {
                o.set(oBase + qi * oStr + tx + 16, new HalfFloat(acc21 * inv));
            }
            if ((qi < t) & (tx + 32 < d)) {
                o.set(oBase + qi * oStr + tx + 32, new HalfFloat(acc22 * inv));
            }
            if ((qi < t) & (tx + 48 < d)) {
                o.set(oBase + qi * oStr + tx + 48, new HalfFloat(acc23 * inv));
            }
        }
        {
            int r = ty + 48;
            int qi = q0 + r;
            float l = lrow[r];
            float inv = l > 0.0f ? 1.0f / l : 0.0f;
            if ((qi < t) & (tx + 0 < d)) {
                o.set(oBase + qi * oStr + tx + 0, new HalfFloat(acc30 * inv));
            }
            if ((qi < t) & (tx + 16 < d)) {
                o.set(oBase + qi * oStr + tx + 16, new HalfFloat(acc31 * inv));
            }
            if ((qi < t) & (tx + 32 < d)) {
                o.set(oBase + qi * oStr + tx + 32, new HalfFloat(acc32 * inv));
            }
            if ((qi < t) & (tx + 48 < d)) {
                o.set(oBase + qi * oStr + tx + 48, new HalfFloat(acc33 * inv));
            }
        }
        if ((tid < 64) & (q0 + tid < t)) {
            float l = lrow[tid];
            lse.set(z * t + q0 + tid, l > 0.0f ? mrow[tid] + TornadoMath.log(l) : MASKED);
        }
    }

    public static void backwardKV(KernelContext kc, HalfFloatArray q, HalfFloatArray k, HalfFloatArray v, FloatArray mask, FloatArray dout, FloatArray lse, FloatArray delta,
            FloatArray dk, FloatArray dv, int t, int s, int d, float scale, int causal, int hasMask, IntArray meta) {
        float[] as = kc.allocateFloatLocalArray(2080);
        float[] bs = kc.allocateFloatLocalArray(2080);
        float[] xs = kc.allocateFloatLocalArray(2080);
        float[] ys = kc.allocateFloatLocalArray(2080);
        float[] ps = kc.allocateFloatLocalArray(1056);
        float[] gs = kc.allocateFloatLocalArray(1056);
        float[] ls = kc.allocateFloatLocalArray(32);
        float[] dl = kc.allocateFloatLocalArray(32);
        int tx = kc.localIdx;
        int ty = kc.localIdy;
        int tid = ty * 16 + tx;
        int blocks = (s + 31) / 32;
        int z = kc.groupIdx / blocks;
        int r0 = (kc.groupIdx - z * blocks) * 32;
        int heads = meta.get(0);
        int b = z / heads;
        int hh = z - b * heads;
        int qBase = meta.get(5) + b * meta.get(6) + hh * meta.get(7);
        int qStr = meta.get(8);
        int kBase = meta.get(9) + b * meta.get(10) + hh * meta.get(11);
        int kStr = meta.get(12);
        int vBase = meta.get(13) + b * meta.get(14) + hh * meta.get(15);
        int vStr = meta.get(16);
        int oBase = meta.get(17) + b * meta.get(18) + hh * meta.get(19);
        int oStr = meta.get(20);
        int mBase = b * meta.get(1) + hh * meta.get(2);
        int mi = meta.get(3);
        int mj = meta.get(4);
        // as = K, bs = V (the work-group's keys); xs = Q, ys = dO (streamed)
        for (int e = tid; e < 2048; e += 256) {
            int r = e / 64;
            int c = e - r * 64;
            int x = r0 + r;
            float u = 0.0f;
            float y = 0.0f;
            if ((x < s) & (c < d)) {
                u = k.get(kBase + x * kStr + c).getFloat32();
                y = v.get(vBase + x * vStr + c).getFloat32();
            }
            as[r * 65 + c] = u;
            bs[r * 65 + c] = y;
        }
        float dk00 = 0.0f;
        float dv00 = 0.0f;
        float dk01 = 0.0f;
        float dv01 = 0.0f;
        float dk02 = 0.0f;
        float dv02 = 0.0f;
        float dk03 = 0.0f;
        float dv03 = 0.0f;
        float dk10 = 0.0f;
        float dv10 = 0.0f;
        float dk11 = 0.0f;
        float dv11 = 0.0f;
        float dk12 = 0.0f;
        float dv12 = 0.0f;
        float dk13 = 0.0f;
        float dv13 = 0.0f;
        int iStart = 0;
        if (causal != 0) {
            iStart = r0;
        }
        for (int i0 = iStart; i0 < t; i0 += 32) {
            for (int e = tid; e < 2048; e += 256) {
                int r = e / 64;
                int c = e - r * 64;
                int x = i0 + r;
                float u = 0.0f;
                float y = 0.0f;
                if ((x < t) & (c < d)) {
                    u = q.get(qBase + x * qStr + c).getFloat32();
                    y = dout.get(oBase + x * oStr + c);
                }
                xs[r * 65 + c] = u;
                ys[r * 65 + c] = y;
            }
            if (tid < 32) {
                float li = MASKED;
                float di = 0.0f;
                if (i0 + tid < t) {
                    li = lse.get(z * t + i0 + tid);
                    di = delta.get(z * t + i0 + tid);
                }
                ls[tid] = li;
                dl[tid] = di;
            }
            kc.localBarrier();
            float s00 = 0.0f;
            float g00 = 0.0f;
            float s01 = 0.0f;
            float g01 = 0.0f;
            float s10 = 0.0f;
            float g10 = 0.0f;
            float s11 = 0.0f;
            float g11 = 0.0f;
            for (int c = 0; c < 64; c++) {
                float a0 = as[(ty + 0) * 65 + c];
                float a20 = bs[(ty + 0) * 65 + c];
                float a1 = as[(ty + 16) * 65 + c];
                float a21 = bs[(ty + 16) * 65 + c];
                float b0 = xs[(tx + 0) * 65 + c];
                float b20 = ys[(tx + 0) * 65 + c];
                float b1 = xs[(tx + 16) * 65 + c];
                float b21 = ys[(tx + 16) * 65 + c];
                s00 += a0 * b0;
                g00 += a20 * b20;
                s01 += a0 * b1;
                g01 += a20 * b21;
                s10 += a1 * b0;
                g10 += a21 * b20;
                s11 += a1 * b1;
                g11 += a21 * b21;
            }
            {
                int kj = r0 + ty + 0;
                int qx = tx + 0;
                int qi = i0 + qx;
                float p = 0.0f;
                float ds = 0.0f;
                float li = ls[qx];
                if ((kj < s) & (qi < t) & ((causal == 0) | (kj <= qi)) & (li > MASKED)) {
                    float sv = s00 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + kj * mj);
                    }
                    p = TornadoMath.exp(sv - li);
                    ds = p * (g00 - dl[qx]);
                }
                ps[(ty + 0) * 33 + tx + 0] = p;
                gs[(ty + 0) * 33 + tx + 0] = ds;
            }
            {
                int kj = r0 + ty + 0;
                int qx = tx + 16;
                int qi = i0 + qx;
                float p = 0.0f;
                float ds = 0.0f;
                float li = ls[qx];
                if ((kj < s) & (qi < t) & ((causal == 0) | (kj <= qi)) & (li > MASKED)) {
                    float sv = s01 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + kj * mj);
                    }
                    p = TornadoMath.exp(sv - li);
                    ds = p * (g01 - dl[qx]);
                }
                ps[(ty + 0) * 33 + tx + 16] = p;
                gs[(ty + 0) * 33 + tx + 16] = ds;
            }
            {
                int kj = r0 + ty + 16;
                int qx = tx + 0;
                int qi = i0 + qx;
                float p = 0.0f;
                float ds = 0.0f;
                float li = ls[qx];
                if ((kj < s) & (qi < t) & ((causal == 0) | (kj <= qi)) & (li > MASKED)) {
                    float sv = s10 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + kj * mj);
                    }
                    p = TornadoMath.exp(sv - li);
                    ds = p * (g10 - dl[qx]);
                }
                ps[(ty + 16) * 33 + tx + 0] = p;
                gs[(ty + 16) * 33 + tx + 0] = ds;
            }
            {
                int kj = r0 + ty + 16;
                int qx = tx + 16;
                int qi = i0 + qx;
                float p = 0.0f;
                float ds = 0.0f;
                float li = ls[qx];
                if ((kj < s) & (qi < t) & ((causal == 0) | (kj <= qi)) & (li > MASKED)) {
                    float sv = s11 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + kj * mj);
                    }
                    p = TornadoMath.exp(sv - li);
                    ds = p * (g11 - dl[qx]);
                }
                ps[(ty + 16) * 33 + tx + 16] = p;
                gs[(ty + 16) * 33 + tx + 16] = ds;
            }
            kc.localBarrier();
            for (int ii = 0; ii < 32; ii++) {
                float p0 = ps[(ty + 0) * 33 + ii];
                float g0 = gs[(ty + 0) * 33 + ii];
                float p1 = ps[(ty + 16) * 33 + ii];
                float g1 = gs[(ty + 16) * 33 + ii];
                float o0 = ys[ii * 65 + tx + 0];
                float q0 = xs[ii * 65 + tx + 0];
                float o1 = ys[ii * 65 + tx + 16];
                float q1 = xs[ii * 65 + tx + 16];
                float o2 = ys[ii * 65 + tx + 32];
                float q2 = xs[ii * 65 + tx + 32];
                float o3 = ys[ii * 65 + tx + 48];
                float q3 = xs[ii * 65 + tx + 48];
                dv00 += p0 * o0;
                dk00 += g0 * q0;
                dv01 += p0 * o1;
                dk01 += g0 * q1;
                dv02 += p0 * o2;
                dk02 += g0 * q2;
                dv03 += p0 * o3;
                dk03 += g0 * q3;
                dv10 += p1 * o0;
                dk10 += g1 * q0;
                dv11 += p1 * o1;
                dk11 += g1 * q1;
                dv12 += p1 * o2;
                dk12 += g1 * q2;
                dv13 += p1 * o3;
                dk13 += g1 * q3;
            }
            kc.localBarrier();
        }
        if (r0 + ty + 0 < s) {
            int j = r0 + ty + 0;
            if (tx + 0 < d) {
                dk.set(kBase + j * kStr + tx + 0, dk00 * scale);
                dv.set(vBase + j * vStr + tx + 0, dv00);
            }
            if (tx + 16 < d) {
                dk.set(kBase + j * kStr + tx + 16, dk01 * scale);
                dv.set(vBase + j * vStr + tx + 16, dv01);
            }
            if (tx + 32 < d) {
                dk.set(kBase + j * kStr + tx + 32, dk02 * scale);
                dv.set(vBase + j * vStr + tx + 32, dv02);
            }
            if (tx + 48 < d) {
                dk.set(kBase + j * kStr + tx + 48, dk03 * scale);
                dv.set(vBase + j * vStr + tx + 48, dv03);
            }
        }
        if (r0 + ty + 16 < s) {
            int j = r0 + ty + 16;
            if (tx + 0 < d) {
                dk.set(kBase + j * kStr + tx + 0, dk10 * scale);
                dv.set(vBase + j * vStr + tx + 0, dv10);
            }
            if (tx + 16 < d) {
                dk.set(kBase + j * kStr + tx + 16, dk11 * scale);
                dv.set(vBase + j * vStr + tx + 16, dv11);
            }
            if (tx + 32 < d) {
                dk.set(kBase + j * kStr + tx + 32, dk12 * scale);
                dv.set(vBase + j * vStr + tx + 32, dv12);
            }
            if (tx + 48 < d) {
                dk.set(kBase + j * kStr + tx + 48, dk13 * scale);
                dv.set(vBase + j * vStr + tx + 48, dv13);
            }
        }
    }

    public static void backwardQ(KernelContext kc, HalfFloatArray q, HalfFloatArray k, HalfFloatArray v, FloatArray mask, HalfFloatArray o, FloatArray dout, FloatArray lse, FloatArray delta,
            FloatArray dq, int t, int s, int d, float scale, int causal, int hasMask, IntArray meta) {
        float[] as = kc.allocateFloatLocalArray(2080);
        float[] bs = kc.allocateFloatLocalArray(2080);
        float[] xs = kc.allocateFloatLocalArray(2080);
        float[] ys = kc.allocateFloatLocalArray(2080);
        float[] ps = kc.allocateFloatLocalArray(1056);
        float[] gs = kc.allocateFloatLocalArray(1056);
        float[] ls = kc.allocateFloatLocalArray(32);
        float[] dl = kc.allocateFloatLocalArray(32);
        int tx = kc.localIdx;
        int ty = kc.localIdy;
        int tid = ty * 16 + tx;
        int blocks = (t + 31) / 32;
        int z = kc.groupIdx / blocks;
        int r0 = (kc.groupIdx - z * blocks) * 32;
        int heads = meta.get(0);
        int b = z / heads;
        int hh = z - b * heads;
        int qBase = meta.get(5) + b * meta.get(6) + hh * meta.get(7);
        int qStr = meta.get(8);
        int kBase = meta.get(9) + b * meta.get(10) + hh * meta.get(11);
        int kStr = meta.get(12);
        int vBase = meta.get(13) + b * meta.get(14) + hh * meta.get(15);
        int vStr = meta.get(16);
        int oBase = meta.get(17) + b * meta.get(18) + hh * meta.get(19);
        int oStr = meta.get(20);
        int mBase = b * meta.get(1) + hh * meta.get(2);
        int mi = meta.get(3);
        int mj = meta.get(4);
        // as = Q, bs = dO (the work-group's queries); xs = K, ys = V (streamed); first xs = O for delta
        for (int e = tid; e < 2048; e += 256) {
            int r = e / 64;
            int c = e - r * 64;
            int x = r0 + r;
            float u = 0.0f;
            float y = 0.0f;
            if ((x < t) & (c < d)) {
                u = q.get(qBase + x * qStr + c).getFloat32();
                y = dout.get(oBase + x * oStr + c);
            }
            as[r * 65 + c] = u;
            bs[r * 65 + c] = y;
        }
        for (int e = tid; e < 2048; e += 256) {
            int r = e / 64;
            int c = e - r * 64;
            float u = 0.0f;
            if ((r0 + r < t) & (c < d)) {
                u = o.get(oBase + (r0 + r) * oStr + c).getFloat32();
            }
            xs[r * 65 + c] = u;
        }
        kc.localBarrier();
        // delta = rowsum(dO * O), 8 threads per row; written for backwardKV, which runs next
        {
            int dr = tid / 8;
            int dc = tid - dr * 8;
            float acc = 0.0f;
            for (int c = 0; c < 8; c++) {
                acc += bs[dr * 65 + dc * 8 + c] * xs[dr * 65 + dc * 8 + c];
            }
            ps[dr * 33 + dc] = acc;
        }
        kc.localBarrier();
        if (tid < 32) {
            float li = MASKED;
            float di = 0.0f;
            for (int c = 0; c < 8; c++) {
                di += ps[tid * 33 + c];
            }
            if (r0 + tid < t) {
                li = lse.get(z * t + r0 + tid);
                delta.set(z * t + r0 + tid, di);
            }
            ls[tid] = li;
            dl[tid] = di;
        }
        kc.localBarrier();
        float dq00 = 0.0f;
        float dq01 = 0.0f;
        float dq02 = 0.0f;
        float dq03 = 0.0f;
        float dq10 = 0.0f;
        float dq11 = 0.0f;
        float dq12 = 0.0f;
        float dq13 = 0.0f;
        int kEnd = s;
        if (causal != 0) {
            int last = r0 + 32;
            kEnd = last < s ? last : s;
        }
        for (int j0 = 0; j0 < kEnd; j0 += 32) {
            for (int e = tid; e < 2048; e += 256) {
                int r = e / 64;
                int c = e - r * 64;
                int x = j0 + r;
                float u = 0.0f;
                float y = 0.0f;
                if ((x < s) & (c < d)) {
                    u = k.get(kBase + x * kStr + c).getFloat32();
                    y = v.get(vBase + x * vStr + c).getFloat32();
                }
                xs[r * 65 + c] = u;
                ys[r * 65 + c] = y;
            }
            kc.localBarrier();
            float s00 = 0.0f;
            float g00 = 0.0f;
            float s01 = 0.0f;
            float g01 = 0.0f;
            float s10 = 0.0f;
            float g10 = 0.0f;
            float s11 = 0.0f;
            float g11 = 0.0f;
            for (int c = 0; c < 64; c++) {
                float a0 = as[(ty + 0) * 65 + c];
                float a20 = bs[(ty + 0) * 65 + c];
                float a1 = as[(ty + 16) * 65 + c];
                float a21 = bs[(ty + 16) * 65 + c];
                float b0 = xs[(tx + 0) * 65 + c];
                float b20 = ys[(tx + 0) * 65 + c];
                float b1 = xs[(tx + 16) * 65 + c];
                float b21 = ys[(tx + 16) * 65 + c];
                s00 += a0 * b0;
                g00 += a20 * b20;
                s01 += a0 * b1;
                g01 += a20 * b21;
                s10 += a1 * b0;
                g10 += a21 * b20;
                s11 += a1 * b1;
                g11 += a21 * b21;
            }
            {
                int qx = ty + 0;
                int qi = r0 + qx;
                int kj = j0 + tx + 0;
                float p = 0.0f;
                float ds = 0.0f;
                float li = ls[qx];
                if ((kj < s) & (qi < t) & ((causal == 0) | (kj <= qi)) & (li > MASKED)) {
                    float sv = s00 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + kj * mj);
                    }
                    p = TornadoMath.exp(sv - li);
                    ds = p * (g00 - dl[qx]);
                }
                ps[(ty + 0) * 33 + tx + 0] = p;
                gs[(ty + 0) * 33 + tx + 0] = ds;
            }
            {
                int qx = ty + 0;
                int qi = r0 + qx;
                int kj = j0 + tx + 16;
                float p = 0.0f;
                float ds = 0.0f;
                float li = ls[qx];
                if ((kj < s) & (qi < t) & ((causal == 0) | (kj <= qi)) & (li > MASKED)) {
                    float sv = s01 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + kj * mj);
                    }
                    p = TornadoMath.exp(sv - li);
                    ds = p * (g01 - dl[qx]);
                }
                ps[(ty + 0) * 33 + tx + 16] = p;
                gs[(ty + 0) * 33 + tx + 16] = ds;
            }
            {
                int qx = ty + 16;
                int qi = r0 + qx;
                int kj = j0 + tx + 0;
                float p = 0.0f;
                float ds = 0.0f;
                float li = ls[qx];
                if ((kj < s) & (qi < t) & ((causal == 0) | (kj <= qi)) & (li > MASKED)) {
                    float sv = s10 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + kj * mj);
                    }
                    p = TornadoMath.exp(sv - li);
                    ds = p * (g10 - dl[qx]);
                }
                ps[(ty + 16) * 33 + tx + 0] = p;
                gs[(ty + 16) * 33 + tx + 0] = ds;
            }
            {
                int qx = ty + 16;
                int qi = r0 + qx;
                int kj = j0 + tx + 16;
                float p = 0.0f;
                float ds = 0.0f;
                float li = ls[qx];
                if ((kj < s) & (qi < t) & ((causal == 0) | (kj <= qi)) & (li > MASKED)) {
                    float sv = s11 * scale;
                    if (hasMask != 0) {
                        sv += mask.get(mBase + qi * mi + kj * mj);
                    }
                    p = TornadoMath.exp(sv - li);
                    ds = p * (g11 - dl[qx]);
                }
                ps[(ty + 16) * 33 + tx + 16] = p;
                gs[(ty + 16) * 33 + tx + 16] = ds;
            }
            kc.localBarrier();
            for (int jj = 0; jj < 32; jj++) {
                float g0 = gs[(ty + 0) * 33 + jj];
                float g1 = gs[(ty + 16) * 33 + jj];
                float k0 = xs[jj * 65 + tx + 0];
                float k1 = xs[jj * 65 + tx + 16];
                float k2 = xs[jj * 65 + tx + 32];
                float k3 = xs[jj * 65 + tx + 48];
                dq00 += g0 * k0;
                dq01 += g0 * k1;
                dq02 += g0 * k2;
                dq03 += g0 * k3;
                dq10 += g1 * k0;
                dq11 += g1 * k1;
                dq12 += g1 * k2;
                dq13 += g1 * k3;
            }
            kc.localBarrier();
        }
        if (r0 + ty + 0 < t) {
            int i = r0 + ty + 0;
            if (tx + 0 < d) {
                dq.set(qBase + i * qStr + tx + 0, dq00 * scale);
            }
            if (tx + 16 < d) {
                dq.set(qBase + i * qStr + tx + 16, dq01 * scale);
            }
            if (tx + 32 < d) {
                dq.set(qBase + i * qStr + tx + 32, dq02 * scale);
            }
            if (tx + 48 < d) {
                dq.set(qBase + i * qStr + tx + 48, dq03 * scale);
            }
        }
        if (r0 + ty + 16 < t) {
            int i = r0 + ty + 16;
            if (tx + 0 < d) {
                dq.set(qBase + i * qStr + tx + 0, dq10 * scale);
            }
            if (tx + 16 < d) {
                dq.set(qBase + i * qStr + tx + 16, dq11 * scale);
            }
            if (tx + 32 < d) {
                dq.set(qBase + i * qStr + tx + 32, dq12 * scale);
            }
            if (tx + 48 < d) {
                dq.set(qBase + i * qStr + tx + 48, dq13 * scale);
            }
        }
    }
}
